select product_id, case when unit_price >= 420 then 'high' when unit_price >= 180 then 'mid' else 'low' end as unit_price_bucket, round(avg(unit_price), 2) as avg_unit_price, count(quantity) as quantity_count from order_items group by product_id, case when unit_price >= 420 then 'high' when unit_price >= 180 then 'mid' else 'low' end having count(quantity) < 1 order by avg_unit_price, 4 desc;
